     1→import {ChainForkConfig} from "@lodestar/config";
     2→import {CheckpointWithHex} from "@lodestar/fork-choice";
     3→import {ForkName, ForkPostFulu, ForkPreGloas, isForkPostDeneb, isForkPostFulu, isForkPostGloas} from "@lodestar/params";
     4→import {computeStartSlotAtEpoch} from "@lodestar/state-transition";
     5→import {RootHex, SignedBeaconBlock, Slot, deneb, fulu} from "@lodestar/types";
     6→import {LodestarError, Logger} from "@lodestar/utils";
     7→import {Metrics} from "../../metrics/metrics.js";
     8→import {IClock} from "../../util/clock.js";
     9→import {CustodyConfig} from "../../util/dataColumns.js";
    10→import {
    11→  BlockInput,
    12→  BlockInputBlobs,
    13→  BlockInputColumns,
    14→  BlockInputPreData,
    15→  BlockWithSource,
    16→  DAType,
    17→  ForkBlobsDA,
    18→  IBlockInput,
    19→  LogMetaBasic,
    20→  LogMetaBlobs,
    21→  LogMetaColumns,
    22→  SourceMeta,
    23→  isBlockInputBlobs,
    24→  isBlockInputColumns,
    25→  isDaOutOfRange,
    26→} from "../blocks/blockInput/index.js";
    27→import {ChainEvent, ChainEventEmitter} from "../emitter.js";
    28→
    29→const MAX_BLOCK_INPUT_CACHE_SIZE = 5;
    30→
    31→export type SeenBlockInputCacheModules = {
    32→  config: ChainForkConfig;
    33→  clock: IClock;
    34→  chainEvents: ChainEventEmitter;
    35→  signal: AbortSignal;
    36→  custodyConfig: CustodyConfig;
    37→  metrics: Metrics | null;
    38→  logger?: Logger;
    39→};
    40→
    41→export type GetByBlobOptions = {
    42→  throwErrorIfAlreadyKnown?: boolean;
    43→};
    44→
    45→/**
    46→ * Consumers that create BlockInputs or change types of old BlockInputs
    47→ *
    48→ * - gossipHandlers (block and blob)
    49→ * - beaconBlocksMaybeBlobsByRange
    50→ * - unavailableBeaconBlobsByRoot (beaconBlocksMaybeBlobsByRoot)
    51→ * - publishBlock in the beacon/blocks/index.ts API
    52→ *   https://github.com/ChainSafe/lodestar/blob/unstable/packages/beacon-node/src/api/impl/beacon/blocks/index.ts#L62
    53→ * - maybeValidateBlobs in verifyBlocksDataAvailability (is_data_available spec function)
    54→ *   https://github.com/ChainSafe/lodestar/blob/unstable/packages/beacon-node/src/chain/blocks/verifyBlocksDataAvailability.ts#L111
    55→ *
    56→ *
    57→ * Pruning management for SeenBlockInputCache
    58→ * ------------------------------------------
    59→ * There are four cases for how pruning needs to be handled
    60→ * - Normal operation following head via gossip (and/or reqresp). For this situation the consumer (process pipeline or
    61→ *   caller of processBlock) will call the `prune` method to remove any processed BlockInputs from the cache. This will
    62→ *   also remove any ancestors of the processed BlockInput as that will also need to have been successfully processed
    63→ *   for import to work correctly
    64→ * - onFinalized event handler will help to prune any non-canonical forks once the chain finalizes. Any block-slots that
    65→ *   are before the finalized checkpoint will be pruned.
    66→ * - Range-sync periods.  The range process uses this cache to store and sync blocks with DA data as the chain is pulled
    67→ *   from peers.  We pull batches, by epoch, so 32 slots are pulled at a time and several batches are pulled concurrently.
    68→ *   It is important to set the MAX_BLOCK_INPUT_CACHE_SIZE high enough to support range sync activities.  Currently the
    69→ *   value is set for 5 batches of 32 slots.  As process block is called (similar to following head) the BlockInput and
    70→ *   its ancestors will be pruned.
    71→ * - Non-Finality times.  This is a bit more tricky.  There can be long periods of non-finality and storing everything
    72→ *   will cause OOM.  The pruneToMax will help ensure a hard limit on the number of stored blocks (with DA) that are held
    73→ *   in memory at any one time.  The value for MAX_BLOCK_INPUT_CACHE_SIZE is set to accommodate range-sync but in
    74→ *   practice this value may need to be massaged in the future if we find issues when debugging non-finality
    75→ */
    76→
    77→export class SeenBlockInput {
    78→  private readonly config: ChainForkConfig;
    79→  private readonly custodyConfig: CustodyConfig;
    80→  private readonly clock: IClock;
    81→  private readonly chainEvents: ChainEventEmitter;
    82→  private readonly signal: AbortSignal;
    83→  private readonly metrics: Metrics | null;
    84→  private readonly logger?: Logger;
    85→  private blockInputs = new Map<RootHex, IBlockInput>();
    86→
    87→  constructor({config, custodyConfig, clock, chainEvents, signal, metrics, logger}: SeenBlockInputCacheModules) {
    88→    this.config = config;
    89→    this.custodyConfig = custodyConfig;
    90→    this.clock = clock;
    91→    this.chainEvents = chainEvents;
    92→    this.signal = signal;
    93→    this.metrics = metrics;
    94→    this.logger = logger;
    95→
    96→    if (metrics) {
    97→      metrics.seenCache.blockInput.blockInputCount.addCollect(() =>
    98→        metrics.seenCache.blockInput.blockInputCount.set(this.blockInputs.size)
    99→      );
   100→    }
   101→
   102→    this.chainEvents.on(ChainEvent.forkChoiceFinalized, this.onFinalized);
   103→    this.signal.addEventListener("abort", () => {
   104→      this.chainEvents.off(ChainEvent.forkChoiceFinalized, this.onFinalized);
   105→    });
   106→  }
   107→
   108→  has(rootHex: RootHex): boolean {
   109→    return this.blockInputs.has(rootHex);
   110→  }
   111→
   112→  get(rootHex: RootHex): IBlockInput | undefined {
   113→    return this.blockInputs.get(rootHex);
   114→  }
   115→
   116→  /**
   117→   * Removes the single BlockInput from the cache
   118→   */
   119→  remove(rootHex: RootHex): void {
   120→    this.blockInputs.delete(rootHex);
   121→  }
   122→
   123→  /**
   124→   * Removes a processed BlockInput from the cache and also removes any ancestors of processed blocks
   125→   */
   126→  prune(rootHex: RootHex): void {
   127→    let blockInput = this.blockInputs.get(rootHex);
   128→    let parentRootHex = blockInput?.parentRootHex;
   129→    let deletedCount = 0;
   130→    while (blockInput) {
   131→      deletedCount++;
   132→      this.blockInputs.delete(blockInput.blockRootHex);
   133→      blockInput = this.blockInputs.get(parentRootHex ?? "");
   134→      parentRootHex = blockInput?.parentRootHex;
   135→    }
   136→    this.logger?.debug(`BlockInputCache.prune deleted ${deletedCount} cached BlockInputs`);
   137→    this.pruneToMaxSize();
   138→  }
   139→
   140→  onFinalized = (checkpoint: CheckpointWithHex) => {
   141→    let deletedCount = 0;
   142→    const cutoffSlot = computeStartSlotAtEpoch(checkpoint.epoch);
   143→    for (const [rootHex, blockInput] of this.blockInputs) {
   144→      if (blockInput.slot < cutoffSlot) {
   145→        deletedCount++;
   146→        this.blockInputs.delete(rootHex);
   147→      }
   148→    }
   149→    this.logger?.debug(`BlockInputCache.onFinalized deleted ${deletedCount} cached BlockInputs`);
   150→    this.pruneToMaxSize();
   151→  };
   152→
   153→  getByBlock({blockRootHex, block, source, seenTimestampSec, peerIdStr}: BlockWithSource): BlockInput {
   154→    // TODO(peerDAS): Why is it necessary to static cast this here. All conditional paths result in a valid value so should be defined correctly below
   155→    let blockInput = this.blockInputs.get(blockRootHex) as IBlockInput;
   156→    if (!blockInput) {
   157→      const {forkName, daOutOfRange} = this.buildCommonProps(block.message.slot);
   158→
   159→      // TODO GLOAS: Implement
   160→      if (isForkPostGloas(forkName)) {
   161→        throw Error("Not implemented");
   162→      }
   163→      // Pre-deneb
   164→      if (!isForkPostDeneb(forkName)) {
   165→        blockInput = BlockInputPreData.createFromBlock({
   166→          block,
   167→          blockRootHex,
   168→          daOutOfRange,
   169→          forkName,
   170→          source,
   171→          seenTimestampSec,
   172→          peerIdStr,
   173→        });
   174→        // Fulu Only
   175→      } else if (isForkPostFulu(forkName)) {
   176→        blockInput = BlockInputColumns.createFromBlock({
   177→          block: block as SignedBeaconBlock<ForkPostFulu & ForkPreGloas>,
   178→          blockRootHex,
   179→          daOutOfRange,
   180→          forkName,
   181→          custodyColumns: this.custodyConfig.custodyColumns,
   182→          sampledColumns: this.custodyConfig.sampledColumns,
   183→          source,
   184→          seenTimestampSec,
   185→          peerIdStr,
   186→        });
   187→        // Deneb and Electra
   188→      } else {
   189→        blockInput = BlockInputBlobs.createFromBlock({
   190→          block: block as SignedBeaconBlock<ForkBlobsDA>,
   191→          blockRootHex,
   192→          daOutOfRange,
   193→          forkName,
   194→          source,
   195→          seenTimestampSec,
   196→          peerIdStr,
   197→        });
   198→      }
   199→      this.blockInputs.set(blockInput.blockRootHex, blockInput);
   200→    }
   201→
   202→    if (!blockInput.hasBlock()) {
   203→      blockInput.addBlock({block, blockRootHex, source, seenTimestampSec, peerIdStr});
   204→    } else {
   205→      this.logger?.debug("Attempt to cache block but is already cached on BlockInput", blockInput.getLogMeta());
   206→      this.metrics?.seenCache.blockInput.duplicateBlockCount.inc({source});
